]

h, w = len(test_input), len(test_input[0])

def solve(grid):
    visited = [[False]*w for _ in range(h)]

    # First pass: identify background (most frequent color)
    counts = {}
    for r in range(h):
        for c in range(w):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    bg = max(counts, key=counts.get)

    # Second pass: find connected components and fill impurities
    for r in range(h):
        for c in range(w):
            if visited[r][c]:
                continue

            val = grid[r][c]

            if val == bg or val == 0:
                visited[r][c] = True
                continue

            comp = []
            stack = [(r, c)]
            seen = {(r, c)}

            while stack:
                cr, cc = stack.pop()
                comp.append((cr, cc))

                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if (nr, nc) not in seen and 0 <= nr < h and 0 <= nc < w:
                        v = grid[nr][nc]
                        if v != bg and v != 0:
                            seen.add((nr, nc))
                            stack.append((nr, nc))

            color_counts = {}
            for cr, cc in comp:
                color_counts[grid[cr][cc]] = color_counts.get(grid[cr][cc], 0) + 1

            dominant = max(color_counts, key=color_counts.get)

            for x, y in comp:
                visited[x][y] = True

    # Fill all pixels in component with dominant color
    result = [row[:] for row in grid]
    for comp, dominant, _ in generate_components(test_input):
        for r, c in comp:
            result[r][c] = dominant
    return result

def generate_components(grid):
    visited = [[False]*w for _ in range(h)]
    regions = []

    for r in range(h):
        for c in range(w):
            if visited[r][c]:
                continue

            val = grid[r][c]
            if val == 9 or val == 0:
                visited[r][c] = True
                continue

            comp = []
            stack = [(r, c)]
            seen = {(r, c)}

            while stack:
                cr, cc = stack.pop()
                comp.append((cr, cc))

                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if (nr, nc) not in seen and 0 <= nr < h and 0 <= nc < w:
                        v = grid[nr][nc]
                        if v != 9 and v != 0:
                            seen.add((nr, nc))
                            stack.append((nr, nc))

            color_counts = {}
            for cr, cc in comp:
                color_counts[grid[cr][cc]] = color_counts.get(grid[cr][cc], 0) + 1

            dominant = max(color_counts, key=color_counts.get)
            regions.append((comp, dominant))
            for x, y in comp:
                visited[x][y] = True

    return regions

result = solve(test_input)

print("Final solution:")
